describe('statistics presentation', () => {
  it('renders cricket scorecards, exact zeroes, undefined rates and neutral tied leaders', () => {
    render(
      <MemoryRouter>
        <FixtureAnalytics statistics={fixtureStatistics} />
      </MemoryRouter>,
    );

