import { fixtureStatisticsQuerySchema } from '@sport-analytics/contracts';
import type { Request, RequestHandler, Response } from 'express';

import type { FixtureStatisticsService } from './fixture-statistics.service';

type AsyncHandler = (request: Request, response: Response) => Promise<void>;

function wrapHandler(handler: AsyncHandler): RequestHandler {
  return (request, response, next) => {
    void handler(request, response).catch(next);
  };
}

function pathParameter(request: Request, name: string): string {
  const value = request.params[name];
  if (value === undefined) {
    throw new Error(`Expected route parameter "${name}" was not provided.`);
  }

  return value;
}

function parseQuery(request: Request, response: Response) {
  const result = fixtureStatisticsQuerySchema.safeParse(request.query);
  if (result.success) {
    return result.data;
  }

  response.status(400).json({
    error: {
      code: 'VALIDATION_FAILED',
      message: 'The request is invalid.',
      details: result.error.issues.map((issue) => ({
        code: 'INVALID_FIELD',
        message: issue.message,
        ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
      })),
    },
  });
  return null;
}

function sendNotFound(response: Response): void {
  response.status(404).json({
    error: {
      code: 'NOT_FOUND',
      message: 'Fixture statistics not found.',
    },
  });
}

export function createFixtureStatisticsController(service: FixtureStatisticsService) {
  return {
    getFixtureStatistics: wrapHandler(async (request, response) => {
      const query = parseQuery(request, response);
      if (!query) {
        return;
      }

      const statistics = await service.getFixtureStatistics(
        pathParameter(request, 'fixtureId'),
        query,
      );
      if (!statistics) {
        sendNotFound(response);
        return;
      }

      response.status(200).json({ data: statistics });
    }),

    getFixtureStatistic: wrapHandler(async (request, response) => {
      const query = parseQuery(request, response);
      if (!query) {
        return;
      }

      const statistic = await service.getFixtureStatistic(
        pathParameter(request, 'fixtureId'),
        pathParameter(request, 'statisticId'),
        query,
      );
      if (!statistic) {
        sendNotFound(response);
        return;
      }

      response.status(200).json({ data: statistic });
    }),
  };
}
import type {
  FixtureStatistic,
  FixtureStatistics,
  FixtureStatisticsQuery,
} from '@sport-analytics/contracts';

import { deriveFixtureStatistics } from './fixture-statistics.derivation';
import {
  createFixtureStatisticsCache,
  type FixtureStatisticsCache,
  type FixtureStatisticsCacheRead,
} from './fixture-statistics.cache';
import type { FixtureStatisticsSource } from './fixture-statistics.model';
import { loadFixtureStatisticsSource } from './fixture-statistics.repository';

export type LoadFixtureStatisticsSource = (
  fixtureId: string,
) => Promise<FixtureStatisticsSource | null>;

export interface FixtureStatisticsService {
  getFixtureStatistics(
    fixtureId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistics | null>;
  getFixtureStatistic(
    fixtureId: string,
    statisticId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistic | null>;
}

const databaseIdPattern = /^\d+$/;

export function createFixtureStatisticsService(
  loadSource: LoadFixtureStatisticsSource = loadFixtureStatisticsSource,
  cache?: FixtureStatisticsCache | null,
): FixtureStatisticsService {
  let resolvedCache = cache;

  function publicStatisticsCache(): FixtureStatisticsCache | null {
    if (resolvedCache === undefined && loadSource === loadFixtureStatisticsSource) {
      resolvedCache = createFixtureStatisticsCache();
    }
    return resolvedCache ?? null;
  }

  // PostgreSQL delivery rows are authoritative and the cache is disposable, so
  // neither cache operation may fail a response the authoritative path can
  // still produce. A failed read falls through to derivation; a failed write
  // leaves the derived response untouched and only costs the next reader a
  // repeated derivation.
  async function readCache(fixtureId: string): Promise<FixtureStatisticsCacheRead | null> {
    try {
      return (await publicStatisticsCache()?.read(fixtureId)) ?? null;
    } catch {
      console.warn('Fixture statistics cache read failed; deriving from PostgreSQL instead.');
      return null;
    }
  }

  async function writeCache(
    fixtureId: string,
    dataVersion: number,
    statistics: FixtureStatistics,
  ): Promise<void> {
    try {
      await publicStatisticsCache()?.write(fixtureId, dataVersion, statistics);
    } catch {
      console.warn('Fixture statistics cache write failed; the derived response is unaffected.');
    }
  }

  async function derive(
    fixtureId: string,
    query: FixtureStatisticsQuery,
  ): Promise<FixtureStatistics | null> {
    if (!databaseIdPattern.test(fixtureId)) {
      return null;
    }

    // Contributor traces are explicit audit/reproduction requests and are not cached.
    const cacheRead = query.includeContributors ? null : await readCache(fixtureId);
    if (cacheRead?.value) return cacheRead.value;

    const source = await loadSource(fixtureId);
    if (!source) {
      return null;
    }

    const statistics = deriveFixtureStatistics(source, {
      includeContributors: query.includeContributors,
    });
    if (cacheRead && !query.includeContributors) {
      await writeCache(fixtureId, cacheRead.dataVersion, statistics);
    }
    return statistics;
  }

  return {
    getFixtureStatistics: derive,

    async getFixtureStatistic(fixtureId, statisticId, query) {
      const fixtureStatistics = await derive(fixtureId, query);
      if (!fixtureStatistics) {
        return null;
      }

      return (
        fixtureStatistics.statistics.find((statistic) => statistic.statisticId === statisticId) ??
        null
      );
    },
  };
}
import type { FixtureStatistics } from '@sport-analytics/contracts';

import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

const fixtureStatisticsCacheTtlSeconds = 60;
const cacheContractVersion = 'v2';
const cacheResource = 'fixture-statistics';

export interface FixtureStatisticsCacheRead {
  dataVersion: number;
  value: FixtureStatistics | null;
}

export interface FixtureStatisticsCache {
  read(fixtureId: string): Promise<FixtureStatisticsCacheRead | null>;
  write(fixtureId: string, dataVersion: number, value: FixtureStatistics): Promise<void>;
}

function cacheKey(fixtureId: string, dataVersion: number): string {
  return `sat:${cacheContractVersion}:${cacheResource}:fixture:${fixtureId}:v${dataVersion}`;
}

function cacheKeyPrefix(fixtureId: string): string {
  return `sat:${cacheContractVersion}:${cacheResource}:fixture:${fixtureId}:v`;
}

interface CacheRow {
  dataVersion: number;
  payload: FixtureStatistics | null;
}

/** Advances the authoritative version in the same transaction as an event write. */
export async function advanceFixtureStatisticsCacheVersions(
  executor: QueryExecutor,
  fixtureIds: readonly string[],
): Promise<void> {
  const uniqueFixtureIds = [...new Set(fixtureIds)];
  if (uniqueFixtureIds.length === 0) return;

  await executeQuery(
    executor,
    `
      WITH advanced AS (
        INSERT INTO fixture_statistics_cache_version (fixture_id, data_version, updated_at)
        SELECT fixture_id, 1, now()
        FROM unnest($1::bigint[]) AS source(fixture_id)
        ON CONFLICT (fixture_id) DO UPDATE
        SET data_version = fixture_statistics_cache_version.data_version + 1,
            updated_at = now()
        RETURNING fixture_id
      )
      DELETE FROM fixture_statistics_cache cache
      USING advanced
      WHERE cache.fixture_id = advanced.fixture_id
    `,
    [uniqueFixtureIds],
  );
}

export function createFixtureStatisticsCache(
  executor: QueryExecutor = getDatabasePool(),
): FixtureStatisticsCache {
  return {
    async read(fixtureId) {
      const result = await executeQuery<CacheRow>(
        executor,
        `
          SELECT COALESCE(version.data_version, 0)::int AS "dataVersion", cache.payload
          FROM fixture
          LEFT JOIN fixture_statistics_cache_version version
            ON version.fixture_id = fixture.fixture_id
          LEFT JOIN fixture_statistics_cache cache
            ON cache.fixture_id = fixture.fixture_id
           AND cache.data_version = COALESCE(version.data_version, 0)
           AND cache.cache_key = $2::text || COALESCE(version.data_version, 0)::text
           AND cache.expires_at > now()
          WHERE fixture.fixture_id = $1::bigint
        `,
        [fixtureId, cacheKeyPrefix(fixtureId)],
      );
      const row = result.rows[0];
      return row ? { dataVersion: row.dataVersion, value: row.payload } : null;
    },

    async write(fixtureId, dataVersion, value) {
      await executeQuery(
        executor,
        `
          INSERT INTO fixture_statistics_cache (
            cache_key, fixture_id, data_version, payload, expires_at
          )
          SELECT $3, fixture.fixture_id, $2::bigint, $4::jsonb,
                 now() + make_interval(secs => $5::int)
          FROM fixture
          LEFT JOIN fixture_statistics_cache_version version
            ON version.fixture_id = fixture.fixture_id
